css:
@page {
    size: A4;
    margin: 10mm !important; /* standard A4 margins */
    padding: 0 !important;
}

body {
    margin: 0 !important;
    padding: 0 !important;
    font-family: "Times New Roman", serif;
    font-size: 15px;
    line-height: 1.4;
    color: #000;
    width: 100% !important;
    height: auto !important; /* Changed from 100% to auto */
    box-sizing: border-box;
    overflow: visible;
}

.print-format {
    margin: 0 !important;
    padding: 0 !important;
    width: 100% !important;
    height: auto !important;
    box-sizing: border-box;
}

.page {
    position: relative;
    width: 198mm; /* Slightly less than 210mm to accommodate padding */
    height: 297mm; /* Fixed A4 height */
    margin: 0 auto;
    overflow: visible; /* allow content overflow */
    box-sizing: border-box;
    padding: 2mm 20mm 20mm 20mm; /* minimal top padding */
}

.page .content {
    position: relative; /* instead of absolute */
    top: 35px; /* you can adjust this */
    left: auto;
    transform: none;
    width: 100%;
    z-index: 2;
    box-sizing: border-box;
    text-align: justify;
    page-break-inside: avoid; /* Prevent awkward page breaks */
}

.content h2 {
    margin-top: 0;
    margin-bottom: 18px;
    font-size: 22px;
    font-weight: bold;
    text-align: center;
}

.content p {
    margin: 0 0 14px 0;
    font-size: 15px;
    text-align: justify;
    text-indent: 30px;
}

.details p {
    text-indent: 0;
    margin: 0 0 10px 0;
}

.signature {
    margin-top: 45px;
    font-size: 15px;
    font-weight: bold;
    text-align: left;
}
